// ─── GET /admin/bundles ────────────────────────────────────────────────────────
adminRouter.get("/admin/bundles", async (req: Request, res: Response) => {
  const cursorParam =
    typeof req.query.cursor === "string" ? req.query.cursor : null;

  let rows: BundleRow[];
  if (cursorParam) {
    rows = await sql<BundleRow[]>`
      SELECT id, name, bundle_type, enabled, required_item_count,
             discount_type, shopify_discount_external_id, discount_code_string,
             purchase_count, created_at, updated_at
      FROM bundles
      WHERE created_at < (SELECT created_at FROM bundles WHERE id = ${cursorParam})
         OR (created_at = (SELECT created_at FROM bundles WHERE id = ${cursorParam}) AND id < ${cursorParam})
      ORDER BY created_at DESC, id DESC
      LIMIT 51
    `;
  } else {
    rows = await sql<BundleRow[]>`
      SELECT id, name, bundle_type, enabled, required_item_count,
             discount_type, shopify_discount_external_id, discount_code_string,
             purchase_count, created_at, updated_at
      FROM bundles
      ORDER BY created_at DESC, id DESC
      LIMIT 51
    `;
  }

  const PAGE_SIZE = 50;
  const hasMore = rows.length > PAGE_SIZE;
  const page = rows.slice(0, PAGE_SIZE);
  const nextCursor = hasMore ? (page[page.length - 1]?.id ?? null) : null;

  // Get total count
  const [countRow] = await sql<{ count: string }[]>`
    SELECT COUNT(*) AS count FROM bundles
  `;
  const totalCount = parseInt(countRow?.count ?? "0", 10);

  const bundles: AdminBundleSummary[] = page.map((r) => ({
    id: r.id,
    name: r.name,
    bundle_type: r.bundle_type,
    enabled: r.enabled,
    purchase_count: r.purchase_count,
  }));

  const response: AdminListBundlesResponse = {
    bundles,
    next_cursor: nextCursor,
    total_count: totalCount,
  };
  res.json(response);
});

